// Hàm tiện ích LocalStorage an toàn trong mọi môi trường (kể cả iframe sandbox)
function safeGetStorage(key, fallback) {
  try {
    const raw = window.localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch (err) {
    return fallback;
  }
}

function safeSetStorage(key, value) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch (err) {
    // Bỏ qua nếu môi trường chặn localStorage
  }
}

// Hiển thị thông báo Toast sang trọng (Không dùng alert/confirm bị chặn)
function showToast(message, type) {
  const container = document.getElementById('toast-container');
  if (!container) return;
  const toast = document.createElement('div');
  const bgClass = type === 'gold'
    ? 'bg-[#4A382D] border-[#D8B66A] text-[#FFF9EF]'
    : 'bg-[#284C40] border-[#D8B66A] text-[#FFF9EF]';
  toast.className = `px-5 py-3.5 rounded-xl border-2 shadow-2xl flex items-center gap-3 text-base font-medium transition-all duration-300 ${bgClass}`;
  toast.innerHTML = `<span class="text-[#D8B66A] text-xl">✦</span><span>${message}</span>`;
  container.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateY(10px)';
    setTimeout(() => {
      if (toast.parentNode) toast.parentNode.removeChild(toast);
    }, 300);
  }, 3600);
}

// Phóng to hình ảnh Lightbox (Đặc biệt cho 4 bức ảnh nghệ thuật của Chị Trịnh Thị An & Hình minh họa sách)
function openLightbox(imgSrc, captionText) {
  const modal = document.getElementById('lightbox-modal');
  const imgEl = document.getElementById('lightbox-img');
  const capEl = document.getElementById('lightbox-caption');
  if (!modal || !imgEl || !capEl) return;
  imgEl.src = imgSrc;
  capEl.textContent = captionText || 'Tác phẩm nghệ thuật – Kho Báu Tri Thức An Nhiên AI — TTA';
  modal.classList.remove('hidden');
}

function closeLightbox() {
  const modal = document.getElementById('lightbox-modal');
  if (modal) modal.classList.add('hidden');
}

// Điều khiển Trải nghiệm Mở Sách Tri Ân Đặc Biệt (Phần 3)
function openGratitudeBookSpread() {
  const closedCover = document.getElementById('book-closed-view');
  const openedSpread = document.getElementById('book-opened-view');
  if (!closedCover || !openedSpread) return;
  closedCover.classList.add('opening');
  setTimeout(() => {
    closedCover.classList.add('hidden');
    openedSpread.classList.remove('hidden');
  }, 380);
}

function enterLibraryFromIntro() {
  const overlay = document.getElementById('intro-book-overlay');
  const skipCheckbox = document.getElementById('skip-intro-checkbox');
  if (skipCheckbox && skipCheckbox.checked) {
    appState.skipIntroNextTime = true;
    safeSetStorage('tta_skip_intro', true);
  }
  if (overlay) {
    overlay.classList.add('hidden-overlay');
  }
  showToast('Chào mừng bạn bước vào Kho Báu Tri Thức – Một Đời Biết Ơn!', 'green');
}

function reopenGratitudeBookModal() {
  const overlay = document.getElementById('intro-book-overlay');
  const closedCover = document.getElementById('book-closed-view');
  const openedSpread = document.getElementById('book-opened-view');
  if (!overlay) return;
  overlay.classList.remove('hidden-overlay');
  if (closedCover && openedSpread) {
    closedCover.classList.add('hidden');
    closedCover.classList.remove('opening');
    openedSpread.classList.remove('hidden');
  }
}

function resetBookToClosedCover() {
  const closedCover = document.getElementById('book-closed-view');
  const openedSpread = document.getElementById('book-opened-view');
  if (!closedCover || !openedSpread) return;
  openedSpread.classList.add('hidden');
  closedCover.classList.remove('hidden', 'opening');
}

// Điều hướng cuộn mượt tới các khu vực và đồng bộ nút Active
function navigateToSection(sectionId) {
  const target = document.getElementById(sectionId);
  if (target) {
    target.scrollIntoView({ behavior: appState.reducedMotion ? 'auto' : 'smooth', block: 'start' });
  }
  document.querySelectorAll('.top-nav-pill').forEach(btn => {
    if (btn.getAttribute('data-target') === sectionId) {
      btn.classList.add('active-nav');
    } else {
      btn.classList.remove('active-nav');
    }
  });
  const mobileMenu = document.getElementById('mobile-nav-drawer');
  if (mobileMenu && !mobileMenu.classList.contains('hidden')) {
    mobileMenu.classList.add('hidden');
  }
}

function toggleMobileMenu() {
  const mobileMenu = document.getElementById('mobile-nav-drawer');
  if (mobileMenu) {
    mobileMenu.classList.toggle('hidden');
  }
}

// Hỗ trợ Người trung niên & lớn tuổi: Thay đổi cỡ chữ & Giảm chuyển động (Phần 4 & 17)

// Tuỳ chỉnh nét bút & màu mực cho TRANG THƯ CỦA TRỊNH THỊ AN trên giấy vở ô ly
function setOliHandwritingStyle(fontMode, inkColor) {
  const root = document.documentElement;
  if (fontMode === "charm") {
    root.style.setProperty("--oli-hand-font", "'Charm', 'Dancing Script', cursive");
  } else {
    root.style.setProperty("--oli-hand-font", "'Dancing Script', 'Charm', cursive");
  }
  if (inkColor) {
    root.style.setProperty("--oli-ink-color", inkColor);
  }
  showToast("Đã cập nhật nét chữ và màu mực cho Trang Thư Của Trịnh Thị An!", "green");
}

function cycleFontSize() {
  appState.fontSizeLevel = (appState.fontSizeLevel + 1) % 3;
  document.body.classList.remove('font-lg', 'font-xl');
  const labelEl = document.getElementById('font-size-label');
  if (appState.fontSizeLevel === 1) {
    document.body.classList.add('font-lg');
    if (labelEl) labelEl.textContent = 'Cỡ chữ: Lớn (Đang bật)';
    showToast('Đã chuyển sang Cỡ chữ Lớn (20px) dễ đọc.', 'green');
  } else if (appState.fontSizeLevel === 2) {
    document.body.classList.add('font-xl');
    if (labelEl) labelEl.textContent = 'Cỡ chữ: Rất lớn (Người cao tuổi)';
    showToast('Đã chuyển sang Cỡ chữ Rất Lớn (22px) dành cho người lớn tuổi.', 'green');
  } else {
    if (labelEl) labelEl.textContent = 'Cỡ chữ: Chuẩn (18px)';
    showToast('Đã chuyển về Cỡ chữ Chuẩn (18px).', 'green');
  }
  safeSetStorage('tta_font_level', appState.fontSizeLevel);
}

function toggleReducedMotion() {
  appState.reducedMotion = !appState.reducedMotion;
  document.body.classList.toggle('reduced-motion', appState.reducedMotion);
  const btn = document.getElementById('reduced-motion-btn');
  if (btn) {
    btn.textContent = appState.reducedMotion ? 'Chuyển động: Đã giảm' : 'Chuyển động: Mượt mà';
  }
  showToast(
    appState.reducedMotion
      ? 'Đã bật chế độ Giảm hiệu ứng chuyển động giúp mắt thư giãn.'
      : 'Đã bật lại hiệu ứng chuyển động mượt mà.',
    'green'
  );
}

