// PHẦN 13: GÓC ÂM NHẠC AN NHIÊN (Không tự phát nhạc, Bật/Tắt/Chuyển bài/Âm lượng + Kết nối YouTube)
function playGentleNote(freq, duration) {
  try {
    if (!appState.audioCtx) {
      const AudioContextClass = window.AudioContext || window.webkitAudioContext;
      if (!AudioContextClass) return;
      appState.audioCtx = new AudioContextClass();
    }
    if (appState.audioCtx.state === 'suspended') {
      appState.audioCtx.resume();
    }
    const osc = appState.audioCtx.createOscillator();
    const gain = appState.audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, appState.audioCtx.currentTime);

    const vol = Math.max(0.02, Math.min(0.9, appState.audioVolume)) * 0.18;
    gain.gain.setValueAtTime(0.001, appState.audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(vol, appState.audioCtx.currentTime + 0.15);
    gain.gain.exponentialRampToValueAtTime(0.0001, appState.audioCtx.currentTime + duration);

    osc.connect(gain);
    gain.connect(appState.audioCtx.destination);
    osc.start();
    osc.stop(appState.audioCtx.currentTime + duration);
  } catch (e) {
    // Bỏ qua nếu trình duyệt chặn âm thanh
  }
}

function toggleMusicPlayback() {
  if (appState.audioPlaying) {
    stopMusicPlayback();
  } else {
    startMusicPlayback();
  }
}

function startMusicPlayback() {
  stopMusicPlayback(false);
  appState.audioPlaying = true;
  const track = appState.music[appState.currentTrackIndex] || appState.music[0];
  let noteIdx = 0;
  playGentleNote(track.notes[0], 1.4);
  appState.audioTimer = setInterval(() => {
    if (!appState.audioPlaying) return;
    noteIdx = (noteIdx + 1) % track.notes.length;
    playGentleNote(track.notes[noteIdx], 1.45);
  }, 1500);
  updateMusicUi();
  showToast(`Đang phát giai điệu đọc sách: ${track.title}`, 'green');
}

function stopMusicPlayback(notify = true) {
  appState.audioPlaying = false;
  if (appState.audioTimer) {
    clearInterval(appState.audioTimer);
    appState.audioTimer = null;
  }
  updateMusicUi();
  if (notify) {
    showToast('Đã tạm dừng nhạc nền đọc sách.', 'gold');
  }
}

function changeMusicTrack(delta) {
  appState.currentTrackIndex = (appState.currentTrackIndex + delta + appState.music.length) % appState.music.length;
  if (appState.audioPlaying) {
    startMusicPlayback();
  } else {
    updateMusicUi();
  }
}

function selectMusicTrackByIndex(idx) {
  appState.currentTrackIndex = idx;
  if (appState.audioPlaying) {
    startMusicPlayback();
  } else {
    updateMusicUi();
  }
}

function handleMusicVolumeChange(val) {
  appState.audioVolume = parseFloat(val);
  const label = document.getElementById('music-volume-label');
  if (label) {
    label.textContent = Math.round(appState.audioVolume * 100) + '%';
  }
}

function updateMusicUi() {
  const track = appState.music[appState.currentTrackIndex] || appState.music[0];
  const titleEl = document.getElementById('music-current-title');
  const subEl = document.getElementById('music-current-subtitle');
  const playBtn = document.getElementById('music-play-toggle-btn');
  const statusBadge = document.getElementById('music-status-badge');
  const listEl = document.getElementById('music-playlist-container');

  if (titleEl && track) titleEl.textContent = track.title;
  if (subEl && track) subEl.textContent = track.subtitle;
  if (playBtn) {
    playBtn.innerHTML = appState.audioPlaying ? '⏸ Tạm dừng nhạc' : '▶ Bật nhạc đọc sách';
    playBtn.className = appState.audioPlaying
      ? 'px-5 py-2.5 rounded-xl bg-[#D8B66A] text-[#284C40] font-bold text-sm cursor-pointer shadow'
      : 'px-5 py-2.5 rounded-xl bg-[#284C40] text-[#FFF9EF] font-bold text-sm cursor-pointer shadow';
  }
  if (statusBadge) {
    statusBadge.textContent = appState.audioPlaying ? '♫ Đang phát nhẹ nhàng' : '○ Đang tắt (Không tự phát)';
  }
  if (listEl) {
    listEl.innerHTML = appState.music.map((m, i) => `
      <button type="button" onclick="selectMusicTrackByIndex(${i})" class="w-full text-left p-3.5 rounded-xl border transition flex items-center justify-between gap-2 cursor-pointer ${i === appState.currentTrackIndex ? 'bg-[#284C40] text-[#FFF9EF] border-[#D8B66A]' : 'bg-[#FFF9EF] text-[#4A382D] border-[#E5D7C3] hover:border-[#284C40]'}">
        <div>
          <p class="font-bold text-sm">${i + 1}. ${m.title}</p>
          <p class="text-xs opacity-80">${m.subtitle}</p>
        </div>
        <span class="text-xs font-semibold px-2.5 py-1 rounded-full ${i === appState.currentTrackIndex ? 'bg-[#D8B66A] text-[#284C40]' : 'bg-white text-[#284C40]'}">
          ${i === appState.currentTrackIndex && appState.audioPlaying ? 'Đang phát' : 'Chọn bài'}
        </span>
      </button>
    `).join('');
  }
}

// PHẦN 14: GÓC TRƯNG BÀY WEBSITE SÁNG TẠO (Cho phép Quản trị viên bổ sung URL & hình ảnh)
function renderPortfolioSites() {
  const container = document.getElementById('portfolio-sites-grid');
  if (!container) return;
  container.innerHTML = appState.portfolio.map(site => {
    const hasUrl = site.url && site.url.trim().length > 0;
    return `
      <article class="p-6 rounded-3xl bg-white border border-[#E5D7C3] shadow-sm flex flex-col justify-between">
        <div>
          <div class="h-36 rounded-2xl mb-4 p-5 flex flex-col justify-between text-[#FFF9EF]" style="background: linear-gradient(135deg, ${site.badgeColor || '#284C40'}, #1B352C);">
            <span class="text-xs uppercase tracking-wider text-[#D8B66A] font-bold">${site.topic}</span>
            <h4 class="font-editorial text-xl font-bold text-[#FFF9EF]">${site.title}</h4>
          </div>
          <span class="inline-block text-xs font-semibold px-2.5 py-1 rounded-full bg-[#F7EFE1] text-[#284C40] mb-2">${site.status}</span>
          <p class="text-sm text-[#4A382D] mb-4 leading-relaxed">${site.desc}</p>
        </div>
        <div class="pt-3 border-t border-[#E5D7C3]">
          ${hasUrl
            ? `<a href="${site.url}" ${site.url.startsWith('http') ? 'target="_blank" rel="noopener noreferrer"' : ''} class="inline-flex items-center justify-center w-full py-2.5 px-4 rounded-xl bg-[#284C40] text-[#FFF9EF] font-semibold text-sm hover:bg-[#1B352C] transition">Khám phá không gian số →</a>`
            : `<span class="inline-flex items-center justify-center w-full py-2.5 px-4 rounded-xl bg-[#F7EFE1] text-[#6E5A4F] font-semibold text-xs">Chờ Quản trị viên cập nhật URL thực tế (Không tạo link giả)</span>`
          }
        </div>
      </article>
    `;
  }).join('');
}

function addPortfolioSiteFromAdmin() {
  const titleEl = document.getElementById('admin-site-title');
  const topicEl = document.getElementById('admin-site-topic');
  const descEl = document.getElementById('admin-site-desc');
  const urlEl = document.getElementById('admin-site-url');
  if (!titleEl || !titleEl.value.trim()) {
    showToast('Vui lòng nhập Tên website đã kiến tạo.', 'gold');
    return;
  }
  const newSite = {
    id: 'site-' + Date.now(),
    title: titleEl.value.trim(),
    topic: (topicEl && topicEl.value.trim()) || 'Không gian số An Nhiên AI',
    desc: (descEl && descEl.value.trim()) || 'Dự án website sáng tạo do Trịnh Thị An – An Nhiên AI xây dựng.',
    url: (urlEl && urlEl.value.trim()) || '',
    status: (urlEl && urlEl.value.trim()) ? 'Đã kết nối URL thực tế' : 'Chờ bổ sung URL',
    badgeColor: '#284C40'
  };
  appState.portfolio.push(newSite);
  safeSetStorage('tta_portfolio', appState.portfolio);
  titleEl.value = '';
  if (topicEl) topicEl.value = '';
  if (descEl) descEl.value = '';
  if (urlEl) urlEl.value = '';
  renderPortfolioSites();
  showToast('Đã bổ sung dự án mới vào Góc Trưng Bày Website!', 'green');
}

// PHẦN 16: CÔNG CỤ QUẢN LÝ & BỔ SUNG SÁCH (Thêm sách, Duyệt bài, Xuất JSON mà không cần viết lại HTML)
function addOrUpdateBookFromAdmin() {
  const titleEl = document.getElementById('admin-book-title');
  const authorEl = document.getElementById('admin-book-author');
  const catEl = document.getElementById('admin-book-category');
  const summaryEl = document.getElementById('admin-book-summary');
  const lifeChangeEl = document.getElementById('admin-book-lifechange');
  const statusEl = document.getElementById('admin-book-status');

  if (!titleEl || !titleEl.value.trim() || !authorEl || !authorEl.value.trim()) {
    showToast('Vui lòng nhập đầy đủ Tên sách và Tác giả xác thực.', 'gold');
    return;
  }

  const catObj = appState.categories.find(c => c.id === (catEl ? catEl.value : 'song-tich-cuc')) || appState.categories[0];
  const isVerified = statusEl && statusEl.value === 'verified';
  const newId = 'book-' + Date.now();
  const titleText = titleEl.value.trim();
  const summaryText = (summaryEl && summaryEl.value.trim()) || 'Đầu sách thuộc kho sách quý Thầy Tuấn Tử Tế Từ Tâm trao tặng.';

  const newBook = {
    id: newId,
    code: 'TTA-NEW-' + (appState.books.length + 1),
    title: titleText,
    author: authorEl.value.trim(),
    category: catObj.id,
    categoryName: catObj.name,
    sourceNote: 'Bổ sung từ Công cụ Quản trị Thư viện An Nhiên AI',
    processStatus: isVerified ? 'verified' : 'pending',
    processLabel: isVerified ? 'Đã biên soạn & kiểm duyệt (12/12 mục)' : 'Đang chờ biên soạn & kiểm duyệt',
    sharePermission: 'analysis_only',
    featured: true,
    recommended: true,
    coverColor: '#284C40',
    coverAccent: '#D8B66A',
    coverSubtitle: summaryText,
    welcomeTitle: `CHÀO MỪNG BẠN ĐẾN VỚI KHÔNG GIAN TRI THỨC CỦA "${titleText.toUpperCase()}"!`,
    welcomeIntro: summaryText,
    lifeChangeQuestion: (lifeChangeEl && lifeChangeEl.value.trim()) || 'Cuốn sách mở ra góc nhìn sâu sắc và bài học ứng dụng thiết thực vào đời sống.',
    summaryShort: summaryText,
    illustration: {
      type: 'self_growth',
      caption: `Hình minh họa biên tập độc lập cho tác phẩm ${titleText}.`
    },
    mindmap: {
      center: `${titleText.toUpperCase()}\n(Sơ đồ tư duy tổng quan)`,
      branches: [
        { title: '1. Tư tưởng cốt lõi', items: [summaryText] },
        { title: '2. Bài học trọng tâm', items: ['Nhận diện giá trị thực tiễn từ tác phẩm'] },
        { title: '3. Hướng dẫn ứng dụng', items: ['Vận dụng vào công việc và gia đình'] },
        { title: '4. Chiêm nghiệm sâu', items: ['Đọc sâu và lan tỏa lòng biết ơn'] }
      ]
    },
    nodes: Array.from({ length: 12 }, (_, idx) => ({
      id: idx + 1,
      label: `${idx + 1}. MỤC KHÁM PHÁ CHUYÊN SÂU SỐ ${idx + 1}`,
      title: `Phân tích chuyên đề mục ${idx + 1} – ${titleText}`,
      summary: summaryText,
      points: [
        'Nội dung được Quản trị viên cập nhật từ hồ sơ phân tích sách đã kiểm duyệt.',
        'Đảm bảo tính xác thực, giáo dục và tôn trọng bản quyền tác giả.'
      ],
      example: 'Vận dụng bài học vào tình huống giao tiếp, công việc và đời sống hàng ngày.',
      application: 'Ghi chú lại 1 ý tâm đắc nhất vào Sổ tay Học tập cá nhân.'
    })),
    researchProblems: []
  };

  appState.books.unshift(newBook);
  safeSetStorage('tta_custom_books', appState.books);
  titleEl.value = '';
  authorEl.value = '';
  if (summaryEl) summaryEl.value = '';
  if (lifeChangeEl) lifeChangeEl.value = '';

  renderFeaturedBooks();
  renderGoalCategories();
  renderBookCatalog();
  renderMemberDashboard();
  openBookExplorer(newId, false);
  showToast(`Đã thêm hồ sơ sách "${titleText}" vào thư viện thành công!`, 'green');
}

function exportLibraryJsonCatalog() {
  const dataStr = JSON.stringify({
    exportedAt: new Date().toISOString(),
    library: 'KHO BÁU TRI THỨC – MỘT ĐỜI BIẾT ƠN (AN NHIÊN AI)',
    categories: appState.categories,
    books: appState.books,
    portfolio: appState.portfolio
  }, null, 2);

  const exportArea = document.getElementById('admin-json-export-box');
  if (exportArea) {
    exportArea.classList.remove('hidden');
    exportArea.value = dataStr;
    exportArea.select();
    try {
      document.execCommand('copy');
      showToast('Đã xuất và sao chép dữ liệu JSON Danh mục sách vào bộ nhớ tạm!', 'green');
    } catch (e) {
      showToast('Đã hiển thị dữ liệu JSON bên dưới để bạn sao chép lưu trữ.', 'green');
    }
  }
}

